'use strict';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('uz-UZ').format(n||0);
const date=v=>v?new Intl.DateTimeFormat('uz-UZ',{timeZone:'Asia/Tashkent',dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
const topicNames={fractions:'Kasrlar',percent:'Foizlar',equations:'Tenglamalar',arithmetic:'Arifmetika'},symbols={fractions:'½',percent:'%',equations:'x',arithmetic:'+'};
const state={user:null,info:null,me:null,test:null,question:0,answers:[],chat:null,routeVersion:0};
const paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',book:'<path d="M3 4h6l3 2 3-2h6v15h-6l-3 2-3-2H3zM12 6v15"/>',map:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><circle cx="7" cy="17" r="2"/><path d="M7 5h10a3 3 0 0 1 0 6H7a3 3 0 0 0 0 6h10"/>',test:'<path d="M7 4H4v17h16V4h-3M8 2h8v5H8zM8 12h8M8 16h5"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z"/><path d="M8 10h8M8 14h5"/>',chart:'<path d="M4 3v18h17M8 16v-4M13 16V8M18 16V4"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 4 5v2"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 3v4l3 2 3-1 3 2 3-2v-3l3-2-1-4-3-1-1-3z"/><circle cx="12" cy="12" r="3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M19 5l-1 1M6 18l-1 1"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',fire:'<path d="M12 2c1 5-4 6-4 10 0-2-2-3-2-3-4 6-1 13 6 13s10-8 6-13c0 3-2 3-2 3 1-5-4-10-4-10Z"/>',shield:'<path d="m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6z"/><path d="m8 12 3 3 5-6"/>',logout:'<path d="M9 3H3v18h6M9 12h12m-5-5 5 5-5 5"/>',telegram:'<path d="m22 3-4 18-6-5-4 3 1-6 9-7-12 6-5-2z"/>',wallet:'<path d="M3 6h18v15H3zM3 6V3h15v3M16 11h5v5h-5z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',send:'<path d="m22 2-7 20-4-9-9-4zM11 13 22 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0v7l-2 3h16l-2-3zM10 21h4"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.spark}</svg>`;
const brand=()=>'<a class="brand" href="#/"><img src="/favicon.svg" alt="">tushundim<span class="accent">.</span></a>';
const themeButton=()=>`<button class="iconbtn theme" aria-label="Rang rejimini almashtirish">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button>`;
try{document.documentElement.dataset.theme=localStorage.getItem('tushundim-theme')||'dark';}catch{}
async function api(url,method='GET',body){const r=await fetch('/api'+url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'Tushundim'},...(body!==undefined?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw new Error('Server bilan aloqa yo‘q. Sahifani localhost:3000 orqali oching.');}if(!r.ok){if(r.status===401&&state.user){state.user=null;location.hash='/login';}throw new Error(d.error||'So‘rov bajarilmadi.');}return d;}
let toastTimer;function toast(text,error=false){const e=$('#toast');e.textContent=text;e.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.className='',5000);}
function go(route){location.hash=route;}
function bindTheme(){ $$('.theme').forEach(b=>b.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('tushundim-theme',next);}catch{}$$('.theme').forEach(x=>x.innerHTML=icon(next==='dark'?'sun':'moon'));});}
function modal(content){$('#modal').innerHTML=`<div class="modal-overlay"><div class="modal-box card" role="dialog" aria-modal="true" aria-label="Amalni tasdiqlash"><div class="row between"><span></span><button class="iconbtn close-modal" aria-label="Yopish">${icon('close')}</button></div>${content}</div></div>`;$('.close-modal').onclick=closeModal;$('.modal-overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal();};$('.modal-box button,.modal-box input')?.focus();}
function closeModal(){$('#modal').innerHTML='';}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('open');}if(e.key==='Tab'&&$('.modal-box')){const nodes=$$('button,a,input,select,textarea',$('.modal-box')).filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
async function action(button,fn){if(button?.disabled)return;if(button)button.disabled=true;try{return await fn();}catch(e){toast(e.message,true);}finally{if(button)button.disabled=false;}}
function formBind(selector,fn){const form=$(selector);if(!form)return;form.onsubmit=async e=>{e.preventDefault();const button=$('button[type=submit]',form);await action(button,()=>fn(Object.fromEntries(new FormData(form)),form));};}
const empty=(title,desc,cta='')=>`<div class="empty">${icon('book')}<h3>${title}</h3><p>${desc}</p>${cta}</div>`;
const stat=(label,value,note,ico='chart')=>`<div class="stat card"><div class="stat-top">${label}${icon(ico)}</div><div class="stat-value">${value}</div><small>${note}</small></div>`;
function priceCards(logged=false){const p=state.info.plans;return `<div class="grid3">${Object.entries(p).map(([key,v])=>`<div class="card price-card ${key==='family'?'highlight':''}">${key==='family'?'<span class="plan-badge">BUTUN OILA UCHUN</span>':''}<div class="eyebrow">${key==='free'?'BIRINCHI QADAM':key==='plus'?'KO‘PROQ IMKONIYAT':'BIRGA O‘SAMIZ'}</div><h3>${v.name}</h3><div class="price">${money(v.price)} <small>so‘m / oy</small></div><p>${key==='free'?'O‘rganishni bugunoq boshlang':key==='plus'?'Har kuni ko‘proq AI yordami':'Farzandlar uchun bitta obuna'}</p><ul><li>${v.children} farzand hisobi</li><li>Kundalik test va cheksiz mashqlar</li><li>Har farzandga kuniga ${v.ai} AI savol</li><li>Bilim xaritasi va natijalar</li><li>Ota-onaga Telegram hisobot</li></ul>${logged?key==='free'?'<span class="pill neutral">Standart bepul imkoniyatlar</span>':`<button class="btn ${key==='family'?'':'secondary'}" data-buy="${key}">Paketni tanlash ${icon('arrow')}</button>`:`<a class="btn ${key==='family'?'':'secondary'}" href="#/register">Boshlash ${icon('arrow')}</a>`}</div>`).join('')}</div>`;}
function landing(){ $('#app').innerHTML=`<div class="public"><nav class="nav-public">${brand()}<div class="navlinks"><a href="#/how">Qanday ishlaydi?</a><a href="#/pricing">Paketlar</a>${themeButton()}<a class="btn secondary" href="#/login">Kirish ${icon('arrow')}</a></div></nav><section class="hero"><div><span class="pill">${icon('spark')} HAR BIR «TUSHUNMADIM» — YANGI BOSHLANISH</span><h1>Bugun tushun.<br>Ertaga <em>ishonch<br>bilan qadam qo‘y.</em></h1><p>Matematikadagi bo‘shliqlarni toping. Sizga mos mashqlar, sabrli AI ustoz va har kuni kichik g‘alabalar bilan oldinga yuring.</p><div class="row"><a class="btn" href="#/register">Bepul boshlash ${icon('arrow')}</a><a class="btn ghost" href="#/how">Qanday ishlaydi?</a></div><div class="hero-note">${icon('shield')} Farzand o‘rganadi. Ota-ona xabardor bo‘ladi.</div></div><div class="hero-visual"><div class="mini-window"><div class="row between mini-top">${brand()}<span>BILIM YO‘LI · NAMUNA</span></div><h3>Katta maqsad. Kichik qadamlar.</h3><div class="path-demo"><div class="path-node"><div class="num">1</div><div><strong>Qayerda qiynalyapsiz?</strong><small>Qisqa test bilan boshlang</small></div></div><div class="path-node active"><div class="num">2</div><div><strong>Sababini birga tushunamiz</strong><small>Xatolar tahlili + vizual mashqlar</small></div>${icon('spark')}</div><div class="path-node"><div class="num">3</div><div><strong>«Endi tushundim!»</strong><small>Yangi test bilan tekshiring</small></div></div></div></div><div class="floating-label">${icon('check')} Natija — taxmin emas<small>Haqiqiy javoblaringizdan hisoblanadi</small></div></div></section><section class="public-section" id="how"><div class="eyebrow">O‘RGANISHNING YANGI RITMI</div><h2>Bitta maqsad. Uchta ishonchli panel.</h2><p>Har kimga o‘ziga kerakli imkoniyat — ortiqcha chalkashliksiz.</p><div class="grid3 space"><div class="card feature">${icon('book')}<h3>Farzand uchun</h3><p>Kundalik testlar, qadam-baqadam darslar, bilim xaritasi va AI bilan savol-javob.</p></div><div class="card feature">${icon('users')}<h3>Ota-ona uchun</h3><p>Farzandingizning o‘sishini kuzating. Natijalarni Telegram orqali oling va birgalikda reja tuzing.</p></div><div class="card feature">${icon('chart')}<h3>Tizim boshqaruvi</h3><p>Haqiqiy foydalanuvchilar, testlar, buyurtmalar va yetkazilgan xabarlar statistikasi.</p></div></div></section><section class="public-section" id="pricing"><div class="eyebrow">SIZGA MOS IMKONIYATLAR</div><h2>O‘sishga joy bor.</h2><p>Taklif etilayotgan boshlang‘ich narxlar. Pullik paket 30 kun amal qiladi.</p><div class="space">${priceCards()}</div></section><footer class="footer"><span>© ${new Date().getFullYear()} Tushundim. Har kuni bir qadam.</span><a href="#/privacy">Maxfiylik va foydalanish</a></footer></div>`;bindTheme();if(['/how','/pricing'].includes(location.hash.slice(1)))setTimeout(()=>$(location.hash.slice(1)==='/how'?'#how':'#pricing')?.scrollIntoView({behavior:'smooth'}),20);}
function authPage(register=false){$('#app').innerHTML=`<div class="auth-wrap"><aside class="auth-story">${brand()}<div><span class="pill">BILIM — O‘ZINGIZGA ISHONCH</span><h1>«Tushunmadim»dan<br><span class="accent">«Tushundim!»gacha.</span></h1><p>Har bir savol — oldinga tashlangan qadam. Birgalikda o‘rganamiz.</p><div class="path-demo"><div class="path-node">${icon('target')} Sizga mos kundalik mashqlar</div><div class="path-node">${icon('chat')} Sabr bilan tushuntiradigan AI ustoz</div><div class="path-node">${icon('users')} Ota-ona bilan birga o‘sish</div></div></div><small>O‘zingizning sur’atingizda. Har kuni.</small></aside><section class="auth-form"><div class="auth-top">${themeButton()}</div><div class="auth-box"><div class="eyebrow">TUSHUNDIMGA XUSH KELIBSIZ</div><h2>${register?'Yangi qadamni boshlang.':'Yana ko‘rishganimizdan xursandmiz.'}</h2><p>${register?'Hisob yarating va bilim yo‘lingizni boshlang.':'Davom etish uchun hisobingizga kiring.'}</p><form id="auth-form">${register?`<div class="roles"><label><input type="radio" name="role" value="student" checked>Farzand</label><label><input type="radio" name="role" value="parent">Ota-ona</label></div><label class="field"><span>Ismingiz</span><input name="name" autocomplete="name" minlength="2" maxlength="60" placeholder="Masalan, Fazliddin" required></label>`:''}<label class="field"><span>Email manzil</span><input type="email" name="email" autocomplete="email" maxlength="120" placeholder="siz@example.com" required></label><label class="field"><span>Parol ${register?'· kamida 10 belgi':''}</span><input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="${register?'10':'1'}" maxlength="72" required placeholder="Parolingizni kiriting"></label>${register?`<label class="field" id="grade-field"><span>Sinfingiz</span><select name="grade">${Array.from({length:9},(_,i)=>`<option value="${i+3}" ${i+3===6?'selected':''}>${i+3}-sinf</option>`).join('')}</select></label><p class="form-note">Ro‘yxatdan o‘tish orqali <a href="#/privacy">maxfiylik qoidalari</a>ni qabul qilasiz. AI savollari tashqi AI xizmatiga yuboriladi. Bolalar ota-onasi bilan birga ro‘yxatdan o‘tsin.</p>`:''}<div id="auth-error"></div><button type="submit" class="btn full space">${register?'Hisob yaratish':'Hisobga kirish'} ${icon('arrow')}</button></form><p class="form-note">${register?'Hisobingiz bormi? <a href="#/login">Kirish</a>':'Hali hisobingiz yo‘qmi? <a href="#/register">Ro‘yxatdan o‘tish</a>'}</p><p class="form-note"><a href="#/">← Bosh sahifaga</a></p></div></section></div>`;bindTheme();$$('input[name=role]').forEach(el=>el.onchange=()=>$('#grade-field').hidden=$('input[name=role]:checked').value==='parent');formBind('#auth-form',async data=>{try{if(register)data.grade=Number(data.grade);const d=await api('/auth/'+(register?'register':'login'),'POST',data);state.user=d.user;state.me=await api('/me');go('/app');}catch(e){$('#auth-error').innerHTML=`<div class="form-error" role="alert">${escapeHTML(e.message)}</div>`;}});}
const navs={student:[['/app','home','Bosh sahifa'],['/app/learn','book','Darslar'],['/app/test','test','Kundalik test'],['/app/map','map','Bilim xaritasi'],['/app/ai','chat','AI ustoz'],['/app/history','chart','Natijalar'],['/app/family','users','Ota-onaga ulanish']],parent:[['/app','home','Oila paneli'],['/app/family','users','Farzandlarim'],['/app/activity','chart','Faoliyat tarixi'],['/app/telegram','telegram','Telegram hisobot']],admin:[['/app','chart','Statistika'],['/app/users','users','Foydalanuvchilar'],['/app/orders','wallet','Buyurtmalar'],['/app/system','shield','Tizim holati']]};
function shell(route){const role=state.user.role;const nav=[...navs[role],...(role==='admin'?[]:[['/app/plans','spark','Paketlar']]),['/app/settings','settings','Sozlamalar']];const title=nav.find(n=>n[0]===route)?.[2]||'O‘rganish';$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="eyebrow">${role==='student'?'MENING BILIM YO‘LIM':role==='parent'?'OILA MAYDONI':'BOSHQARUV'}</div><nav class="sidenav">${nav.map(([url,ico,name])=>`<a href="#${url}" class="${route===url?'active':''}">${icon(ico)}${name}</a>`).join('')}</nav><div class="side-bottom">${role!=='admin'?`<div class="upgrade">${icon('spark')}<h3>Birga o‘sish osonroq</h3><p>Oila paketi bilan 4 farzandgacha bitta hisobda.</p><a class="btn small full" href="#/app/plans">Paketlarni ko‘rish ${icon('arrow')}</a></div>`:''}<div class="profile-chip"><div class="avatar">${escapeHTML(state.user.name.slice(0,1).toUpperCase())}</div><div class="grow"><strong>${escapeHTML(state.user.name)}</strong><small>${role==='student'?'O‘quvchi':role==='parent'?'Ota-ona':'Administrator'}</small></div><button class="iconbtn logout" aria-label="Hisobdan chiqish">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="iconbtn mobile-toggle" aria-label="Menyuni ochish">${icon('menu')}</button><span class="breadcrumb">Mening maydonim &nbsp; / &nbsp; <b>${title}</b></span></div><div class="row"><small class="topbar-date">${new Intl.DateTimeFormat('uz-UZ',{dateStyle:'long',timeZone:'Asia/Tashkent'}).format(new Date())}</small>${themeButton()}<a href="#/app/settings" class="avatar" aria-label="Profil">${escapeHTML(state.user.name[0].toUpperCase())}</a></div></header><div class="content" id="view"><div class="loading">Ma’lumotlar yuklanmoqda…</div></div></main></div>`;bindTheme();$('.logout').onclick=e=>action(e.currentTarget,async()=>{await api('/auth/logout','POST');state.user=null;state.test=null;state.chat=null;go('/login');});$('.mobile-toggle').onclick=()=>$('.sidebar').classList.toggle('open');}
function head(title,description,extra=''){return `<div class="page-head"><div><div class="eyebrow">${state.user.role==='student'?'BILIM YO‘LINGIZ DAVOM ETADI':state.user.role==='parent'?'HAR QADAMDAN XABARDOR BO‘LING':'HAQIQIY MA’LUMOTLAR'}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function topicRows(rows){return rows.map(t=>`<a href="#/app/learn/${t.id}" class="topic-row"><div class="topic-symbol">${symbols[t.id]}</div><div class="grow"><h3>${t.name}</h3><small>${t.count?t.count+' ta topshirilgan test':'Hali tekshirilmagan'}</small><progress value="${t.mastery||0}" max="100" aria-label="${t.name} o‘zlashtirish"></progress></div><div class="topic-value">${t.mastery===null?'—':t.mastery+'%'}<br><small>${t.mastery===null?'Boshlang':t.mastery<60?'Mashq kerak':'Davom eting'}</small></div></a>`).join('');}
function activities(rows){return rows.length?rows.map(a=>`<div class="activity-row"><div class="activity-dot">${icon(a.type==='test'?'test':a.type==='ai'?'chat':'check')}</div><div><p>${a.userId?.name?`<strong>${escapeHTML(a.userId.name)}</strong> · `:''}${escapeHTML(a.text)}</p><small>${date(a.createdAt)}</small></div></div>`).join(''):empty('Hali faoliyat yo‘q','Birinchi dars yoki testdan so‘ng bu yer yangilanadi.');}
async function studentHome(){const [s,a]=await Promise.all([api('/dashboard'),api('/activities')]);return `${head(`Salom, ${escapeHTML(state.user.name.split(' ')[0])}! 👋`,'Bugungi kichik qadam — ertangi katta ishonch.',`<span class="pill">${icon('fire')} ${s.streak} kunlik ketma-ketlik</span>`)}<div class="welcome-banner"><div><span class="pill neutral">KUNLIK MAQSAD · 10 TA SAVOL</span><h2>${s.dailyDone?'Bugungi vazifa bajarildi. Barakalla!':'Bugun nimani tushunib olamiz?'}</h2><p>${s.dailyDone?'Bilimingizni mustahkamlash uchun qo‘shimcha mashq qiling yoki AI ustozga savol bering.':'Mavzuni tanlang, o‘zingizni sinang va aynan qayerda mashq kerakligini bilib oling.'}</p><a class="btn" href="#/app/test">${s.dailyDone?'Mashqni davom ettirish':'Kundalik testni boshlash'} ${icon('arrow')}</a></div><div class="orb">${icon('book')}</div></div><div class="grid4">${stat('Jami to‘plangan XP',money(s.xp),'Har to‘g‘ri javob uchun +10 XP','spark')}${stat('Yakunlangan testlar',s.tests,'Sizning haqiqiy natijalaringiz','test')}${stat('O‘rtacha natija',s.average+'%','Barcha yakunlangan testlar','target')}${stat('Ketma-ket o‘qish',s.streak+' kun','Toshkent vaqti bo‘yicha','fire')}</div><div class="dashboard-columns"><section class="card"><div class="section-head"><h2>Bilim xaritangiz</h2><a class="muted" href="#/app/map">Barchasi ↗</a></div>${topicRows(s.byTopic)}<div class="tip-card"><h3>${icon('spark')} Raqam ortidagi ma’no</h3><p>Foiz — shu mavzudagi oxirgi 3 ta test natijasining o‘rtachasi. Kam natijali mavzuni qayta mashq qiling.</p></div></section><section class="card"><div class="section-head"><h2>Oxirgi qadamlar</h2>${icon('clock')}</div>${activities(a.slice(0,4))}<a class="btn ghost small full space" href="#/app/history">Barcha natijalar ${icon('arrow')}</a></section></div>`;}
async function learnPage(topic){const lessons=await api('/lessons');if(!topic)return `${head('Tushunish shu yerdan boshlanadi.','Qisqa dars. Hayotiy misol. O‘zingiz sinab ko‘radigan mashq.')}<div class="grid2">${lessons.map(l=>`<article class="card lesson-card"><div class="lesson-art">${symbols[l.id]}</div><div class="row between"><span class="pill">${l.tag}</span><small>${icon('clock')} ${l.duration}</small></div><h2>${l.title}</h2><p>${l.text}</p><a class="btn secondary" href="#/app/learn/${l.id}">Darsni ochish ${icon('arrow')}</a></article>`).join('')}</div>`;
 const l=lessons.find(x=>x.id===topic);if(!l)throw new Error('Dars topilmadi.');return `<div class="lesson-view"><a class="btn ghost small" href="#/app/learn">${icon('back')} Darslarga qaytish</a><h1>${l.title}</h1><div class="row"><span class="pill">${l.tag}</span><small>${l.duration}</small></div><section class="card space"><p class="explanation">${l.text}</p><div class="example">${l.example}</div><h3>Endi o‘zingiz sinang</h3><p class="space">${l.task}</p><form id="lesson-form" data-topic="${l.id}">${l.id==='fractions'?`<div class="segments">${Array.from({length:8},(_,i)=>`<button class="segment" type="button" aria-pressed="false" data-segment="${i}">${i+1}</button>`).join('')}</div><p id="fraction-count">0 / 8 bo‘lak tanlandi</p>`:l.id==='percent'?'<label class="field space"><span>Chegirma foizi</span><input id="discount" type="range" min="0" max="100" step="5" value="20"></label><div class="range-value" id="discount-result">160 000 so‘m</div><label class="field"><span>Tekshiruv: 200 000 so‘mga 20% chegirmadan keyingi narx?</span><input type="number" name="answer" required placeholder="Javobni yozing"></label>':`<label class="field space"><span>${l.id==='equations'?'x qiymati':'Javob'}</span><input type="number" name="answer" required placeholder="Javobni yozing"></label>`}<button class="btn space" type="submit">Javobni tekshirish ${icon('check')}</button><div id="lesson-feedback" class="space" role="status"></div></form></section></div>`;}
function bindLesson(){const form=$('#lesson-form');if(!form)return;$$('.segment').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');b.setAttribute('aria-pressed',b.classList.contains('selected'));$('#fraction-count').textContent=$$('.segment.selected').length+' / 8 bo‘lak tanlandi';});if($('#discount'))$('#discount').oninput=e=>$('#discount-result').textContent=money(200000*(1-e.target.value/100))+' so‘m';formBind('#lesson-form',async(data)=>{const topic=form.dataset.topic;const answer=topic==='fractions'?$$('.segment.selected').length:Number(data.answer);await api(`/lessons/${topic}/complete`,'POST',{answer});$('#lesson-feedback').innerHTML='<span class="pill">✓ To‘g‘ri! Dars mashqi bajarildi.</span> <a class="btn small secondary" href="#/app/test">Testda sinash →</a>';toast('Barakalla! Natija saqlandi.');});}
async function testPage(){if(state.test)return renderQuestion();const s=await api('/dashboard');return `${head('O‘zingizni sinab ko‘ring.','Javoblaringiz saqlanadi, natija va tushuntirishlarni yakunda ko‘rasiz.')}<div class="grid2"><form class="card" id="start-test"><div class="row between"><h2>Bugungi mashq</h2><span class="pill">10 TA SAVOL</span></div><label class="field space"><span>Mashq turi</span><select name="kind"><option value="daily">Kundalik test ${s.dailyDone?'· bajarilgan':''}</option><option value="practice">Qo‘shimcha mashq</option></select></label><label class="field"><span>Mavzu</span><select name="topic">${Object.entries(topicNames).map(([k,v])=>`<option value="${k}" ${state.user.topic===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Qiyinlik</span><select name="level"><option value="1">Boshlang‘ich · kichik sonlar</option><option value="2">O‘rtacha · kattaroq sonlar</option><option value="3">Murakkabroq · ko‘proq hisoblash</option></select></label><button class="btn full" type="submit">Testni boshlash ${icon('arrow')}</button></form><div class="card"><div class="orb">${icon('target')}</div><h2 class="space">Xato qilish mumkin.</h2><p class="space">Bu baho uchun musobaqa emas. Qaysi mavzuni yana ko‘rib chiqish kerakligini aniqlash uchun mashq.</p><div class="tip-card"><h3>Natija qanday hisoblanadi?</h3><p>Har bir to‘g‘ri javob — 10 XP. Kundalik test kuniga bir marta. Qo‘shimcha mashqlar cheksiz. Bir testni qayta yuborish XP ni ko‘paytirmaydi.</p></div><p class="space">Kundalik test Toshkent vaqti bilan yangi kunda ochiladi. Boshlangan kundalik test qayta ochilsa, o‘sha savollar ko‘rsatiladi.</p></div></div>`;}
function renderQuestion(){const t=state.test,q=t.questions[state.question];return `<div class="test-wrap">${head(topicNames[t.topic],t.kind==='daily'?'Kundalik test':'Qo‘shimcha mashq',`<span class="pill">${state.question+1} / ${t.questions.length}</span>`)}<section class="card"><div class="row between"><span class="question-label">${state.question+1}-SAVOL</span><button class="btn ghost small" id="leave-test">Keyin davom etaman</button></div><progress class="test-progress" value="${state.question+1}" max="${t.questions.length}" aria-label="Test bosqichi"></progress><h2 class="question">${escapeHTML(q.prompt)}</h2><div class="answers">${q.options.map((o,i)=>`<button class="answer ${state.answers[state.question]===o?'selected':''}" data-answer="${o}"><span>${'ABCD'[i]}</span>${o}</button>`).join('')}</div><div class="test-actions"><button class="btn ghost" id="prev-question" ${state.question===0?'disabled':''}>${icon('back')} Oldingi</button><button class="btn" id="next-question" ${state.answers[state.question]===undefined?'disabled':''}>${state.question===9?'Natijani ko‘rish':'Keyingi'} ${icon('arrow')}</button></div></section></div>`;}
function resultHTML(r){return `<div class="test-wrap"><section class="card result-hero"><span class="pill">TEST YAKUNLANDI</span><div class="result-score">${r.score}<span class="muted">/${r.total}</span></div><h2>${r.score>=8?'Barakalla, yaxshi ketayapsiz!':r.score>=5?'Yaxshi boshlanish. Davom etamiz!':'Xatolar — keyingi dars uchun yo‘l xaritasi.'}</h2><p class="space">${r.score*10} XP · ${Math.round(r.score/r.total*100)}% to‘g‘ri javob. Natija hisobingizda saqlandi.</p><div class="row wrap space"><a class="btn" href="#/app/map">Bilim xaritasi ${icon('arrow')}</a><button class="btn secondary" id="another-test">Yana mashq qilish</button></div></section><section class="card space"><h2>Javoblar tahlili</h2>${r.review.map((x,i)=>`<div class="review-row"><span class="${x.correct?'score':'wrong'}">${x.correct?'✓ To‘g‘ri':'↺ Qayta ko‘rib chiqamiz'} · ${i+1}-savol</span><h3>${escapeHTML(x.prompt)}</h3><p>Sizning javobingiz: <strong>${escapeHTML(x.given)}</strong> · To‘g‘ri javob: <strong>${x.answer}</strong></p><p class="space">${escapeHTML(x.explanation)}</p></div>`).join('')}</section></div>`;}
function bindTests(){formBind('#start-test',async d=>{const t=await api('/tests/start','POST',{...d,level:Number(d.level)});if(t.done){go('/app/result/'+t.id);return;}state.test=t;state.question=0;state.answers=[];$('#view').innerHTML=renderQuestion();bindTests();});$$('[data-answer]').forEach(b=>b.onclick=()=>{state.answers[state.question]=Number(b.dataset.answer);$('#view').innerHTML=renderQuestion();bindTests();});if($('#prev-question'))$('#prev-question').onclick=()=>{state.question--;$('#view').innerHTML=renderQuestion();bindTests();};if($('#next-question'))$('#next-question').onclick=e=>action(e.currentTarget,async()=>{if(state.question<9){state.question++;$('#view').innerHTML=renderQuestion();bindTests();}else{if(state.answers.filter(v=>v!==undefined).length!==10)throw new Error('Barcha savollarga javob bering.');await api(`/tests/${state.test.id}/submit`,'POST',{answers:state.answers});const id=state.test.id;state.test=null;state.answers=[];go('/app/result/'+id);}});if($('#leave-test'))$('#leave-test').onclick=()=>go('/app');if($('#another-test'))$('#another-test').onclick=()=>{state.test=null;go('/app/test');};}
async function mapPage(){const s=await api('/dashboard');const low=s.byTopic.filter(t=>t.mastery!==null).sort((a,b)=>a.mastery-b.mastery)[0];return `${head('Bilim xaritangiz.','Natijalar nimani bilishingiz va nimani mustahkamlash kerakligini ko‘rsatadi.')}<div class="notice">Bu xarita — test natijalarining ko‘rsatkichi. U to‘liq pedagogik tashxis yoki barcha bilimlaringiz bahosi emas.</div><div class="grid2"><section class="card"><h2>Mavzular bo‘yicha</h2>${topicRows(s.byTopic)}</section><section class="card"><span class="pill">KEYINGI QADAM</span><h2 class="space">${low?topicNames[low.id]+'ni mustahkamlaymiz':'Poydevordan boshlaymiz'}</h2><p class="space">${low?`Shu mavzudagi oxirgi testlar o‘rtachasi ${low.mastery}%. Darsni ko‘rib chiqing, keyin yangi misollarda sinab ko‘ring.`:'Hali yetarli natija yo‘q. Birinchi testni yeching — xarita haqiqiy javoblaringiz asosida shakllanadi.'}</p><a class="btn space" href="#/app/learn/${low?.id||'arithmetic'}">Darsni ochish ${icon('arrow')}</a><div class="tip-card"><h3>Tavsiya etiladigan tartib</h3><p>Arifmetika → Kasrlar → Foizlar → Tenglamalar. Har bosqichda tushunganingizni mashq bilan tekshiring.</p></div></section></div>`;}
async function historyPage(){const s=await api('/dashboard');return `${head('Natijalaringiz — o‘sish tarixi.','Oxirgi 8 ta testning to‘liq javoblarini qayta ko‘rishingiz mumkin.')}<div class="grid3">${stat('Yakunlangan testlar',s.tests,'Barcha vaqt','test')}${stat('Jami XP',s.xp,'Faqat tekshirilgan javoblar','spark')}${stat('O‘rtacha natija',s.average+'%','Barcha testlar bo‘yicha','chart')}</div><section class="card space">${s.recent.length?`<div class="table-wrap"><table><thead><tr><th>Mavzu</th><th>Turi</th><th>Natija</th><th>Vaqt</th><th>Tahlil</th></tr></thead><tbody>${s.recent.map(r=>`<tr><td>${topicNames[r.topic]}</td><td>${r.kind==='daily'?'Kundalik':'Mashq'}</td><td class="score">${r.score}/${r.total}</td><td>${date(r.finishedAt)}</td><td><a class="btn small ghost" href="#/app/result/${r.id}">Ko‘rish →</a></td></tr>`).join('')}</tbody></table></div>`:empty('Birinchi natijangizni kutyapmiz','Test yeching — natija shu yerda paydo bo‘ladi.','<a class="btn" href="#/app/test">Testni boshlash</a>')}</section>`;}
async function familyPage(home=false){if(state.user.role==='student')return `${head('Ota-onangiz bilan bir jamoa.','Faqat bir martalik kodni ota-onangizga bering.')}<div class="card settings-section">${state.user.parentId?`<span class="pill">${icon('check')} OTA-ONA HISOBI ULANGAN</span><h2 class="space">Birga o‘sish boshlandi.</h2><p class="space">Ota-onangiz natijalar va sayt ichidagi o‘quv faoliyatingizni ko‘radi. Telegramni yoqsa, kirish, dars va test haqidagi xabarlar boradi. AI suhbatlaringizning matni yuborilmaydi.</p>`:`<h2>Ulanish uchun 3 qadam</h2><ol><li>Quyidagi tugma orqali kod oling.</li><li>Ota-onangiz o‘z hisobiga kirsin.</li><li>«Farzand qo‘shish» bo‘limiga kodni kiritsin.</li></ol><button class="btn" id="family-code">Bir martalik kod olish ${icon('plus')}</button><div id="generated-code"></div><p class="space">Kod 10 daqiqa amal qiladi. Uni faqat ota-onangiz bilan ulashing.</p>`}</div>`;
 const [children,a]=await Promise.all([api('/family'),home?api('/activities'):Promise.resolve([])]);return `${head(home?`Oilangizning bilim maydoni.`:'Farzandlarim.','Farzandingizning harakatini ko‘ring, kichik yutuqlarini birga nishonlang.',`<button class="btn" id="add-child">${icon('plus')} Farzand qo‘shish</button>`)}<div class="notice">${icon('shield')} Farzandlar faqat o‘zlari bergan kod orqali ulanadi. Shaxsiy AI suhbat matnlari ota-ona panelida ko‘rsatilmaydi.</div>${children.length?`<div class="grid2">${children.map(({user:u,summary:s})=>`<article class="card child-card"><div class="row between"><div class="row"><div class="avatar">${escapeHTML(u.name[0])}</div><div><h3>${escapeHTML(u.name)}</h3><small>${u.grade}-sinf · ${s.dailyDone?'Bugungi test bajarilgan':'Bugungi test hali bajarilmagan'}</small></div></div><span class="pill">${s.streak} kun</span></div><div class="child-stats"><div><strong>${s.tests}</strong><small>TEST</small></div><div><strong>${s.average}%</strong><small>O‘RTACHA</small></div><div><strong>${s.xp}</strong><small>XP</small></div></div>${topicRows(s.byTopic).replaceAll('href="#/app/learn/','href="#/app/family?topic=')}<div class="tip-card"><h3>Bugun qanday yordam berish mumkin?</h3><p>${s.tests?'Eng past natijali mavzuni birga muhokama qiling. Xatosi uchun koyimang, qanday yechganini so‘rang.':'Birinchi 10 savollik testni tinch joyda yechishga sharoit yarating.'}</p></div><button class="btn danger small space" data-unlink="${u.id}" data-name="${escapeHTML(u.name)}">Oiladan ajratish</button></article>`).join('')}</div>`:empty('Birinchi farzandingizni ulang','Farzand hisobidagi «Ota-onaga ulanish» bo‘limidan kod oling.')}<div class="grid2 space"><section class="card"><div class="row between"><h2>Telegram bilan yaqinroq</h2>${icon('telegram')}</div><p class="space">Kirish, dars mashqi, AI faoliyati va test natijalari — bitta botda. Xabarlarni istalgan payt to‘xtatish mumkin.</p><a href="#/app/telegram" class="btn secondary space">Telegramni sozlash ${icon('arrow')}</a></section>${home?`<section class="card"><h2>So‘nggi faoliyat</h2>${activities(a.slice(0,4))}</section>`:`<section class="card"><h2>Oila paketi</h2><p class="space">4 farzandgacha ulash va har biriga ko‘proq AI savollari.</p><a href="#/app/plans" class="btn secondary space">Paketlarni ko‘rish ${icon('arrow')}</a></section>`}</div>`;}
function bindFamily(){if($('#family-code'))$('#family-code').onclick=e=>action(e.currentTarget,async()=>{const d=await api('/family/code','POST');$('#generated-code').innerHTML=`<div class="code-box">${d.code}</div><small>${d.expiresMinutes} daqiqa amal qiladi.</small> <button class="btn small ghost" id="copy-code">Nusxalash</button>`;$('#copy-code').onclick=e=>action(e.currentTarget,async()=>{await navigator.clipboard.writeText(d.code);toast('Kod nusxalandi.');});});if($('#add-child'))$('#add-child').onclick=()=>{modal(`<h2>Farzandni ulash</h2><p>Farzandingizning «Ota-onaga ulanish» bo‘limidagi 24 belgili kodni kiriting.</p><form id="link-child"><label class="field"><span>Bir martalik kod</span><input name="code" required minlength="24" maxlength="24" autocomplete="off" placeholder="Kod"></label><button type="submit" class="btn full">Farzandni ulash</button></form>`);formBind('#link-child',async d=>{await api('/family/link','POST',d);closeModal();toast('Farzand muvaffaqiyatli ulandi.');await route();});};$$('[data-unlink]').forEach(b=>b.onclick=()=>{modal(`<h2>Oiladan ajratilsinmi?</h2><p>${escapeHTML(b.dataset.name)} hisobining o‘zi va test natijalari o‘chmaydi. Sizga yangi natijalar kelmaydi.</p><button class="btn danger" id="confirm-unlink">Ha, oiladan ajratish</button>`);$('#confirm-unlink').onclick=e=>action(e.currentTarget,async()=>{await api('/family/'+b.dataset.unlink,'DELETE');closeModal();await route();toast('Hisob oiladan ajratildi.');});});}
async function telegramPage(){const s=await api('/telegram/status');return `${head('Hisobotlar — Telegramingizda.','Sayt ichidagi o‘qish faoliyati haqida vaqtida xabardor bo‘ling.')}<div class="grid2"><section class="card"><div class="row between"><h2>Tushundim bot</h2>${icon('telegram')}</div><span class="pill space">${s.enabled?'ULANGAN':'HALI ULANMAGAN'}</span><p class="space">Telegram bot faqat shaxsiy chatga ulanadi. Havolani bosib, bot ichida <strong>Start</strong> tugmasini bosing.</p><div class="tip-card"><h3>Qanday xabarlar keladi?</h3><p>Saytga kirish · dars mashqini bajarish · test natijasi · AI bilan mashq qilganlik. Suhbat matni va sayt tashqarisidagi faoliyat yuborilmaydi.</p></div><button class="btn space" id="telegram-link">${icon('telegram')} ${s.enabled?'Qayta ulash':'Telegramni ulash'}</button>${s.enabled?'<button class="btn ghost space" id="telegram-off">Xabarlarni o‘chirish</button>':''}<div id="telegram-url"></div><p class="space">Bot buyruqlari: <strong>/report</strong> — oxirgi natijalar, <strong>/stop</strong> — xabarlarni to‘xtatish.</p></section><section class="card"><h2>Yetkazish holati</h2><p class="space">Xabarlar server ishlab turgan paytda yuboriladi. Vaqtinchalik xatolarda avtomatik qayta uriniladi.</p>${s.recent.length?s.recent.map(r=>`<div class="activity-row"><div><span class="pill neutral">${({sent:'Yuborildi',pending:'Navbatda',failed:'Yuborilmadi',cancelled:'Bekor qilindi'})[r.status]}</span><p class="space">${escapeHTML(r.text)}</p><small>${date(r.createdAt)}</small></div></div>`).join(''):empty('Hali xabarlar yo‘q','Botni ulang, keyin farzandingiz test bajarsin.')}</section></div>`;}
function bindTelegram(){if($('#telegram-link'))$('#telegram-link').onclick=e=>action(e.currentTarget,async()=>{const d=await api('/telegram/link','POST');$('#telegram-url').innerHTML=`<a class="btn secondary space" href="${escapeHTML(d.url)}" target="_blank" rel="noopener noreferrer">Botni Telegramda ochish ↗</a><p class="space">Botda Start tugmasini bosganingizdan so‘ng bu sahifani yangilang.</p><button id="refresh-telegram" class="btn ghost small space">Ulanishni tekshirish</button>`;$('#refresh-telegram').onclick=()=>route();});if($('#telegram-off'))$('#telegram-off').onclick=e=>action(e.currentTarget,async()=>{await api('/telegram/link','DELETE');await route();toast('Telegram hisobotlari o‘chirildi.');});}
async function aiPage(){const chats=await api('/chats');if(state.chat&&!chats.some(c=>c._id===state.chat._id))state.chat=null;if(!state.chat&&chats.length)state.chat=await api('/chats/'+chats[0]._id);return `${head('Savollaringizga joy bor.','AI ustoz bilan tushuning, sinang va savol-javob o‘ynang.')}<div class="notice">${state.info.aiConfigured?'AI xato qilishi mumkin. Muhim javoblarni dars va o‘qituvchingiz bilan tekshiring. Shaxsiy ma’lumot yozmang.':'AI hali ulanmagan. Serverga OPENAI_API_KEY qo‘shilgandan so‘ng suhbatlar ishlaydi. Darslar va testlar hozir ham mavjud.'} · Kunlik limit: ${state.me.entitlements.ai} savol.</div><div class="chat-layout"><aside class="card chat-list"><button class="btn full small" id="new-chat">${icon('plus')} Yangi suhbat</button>${chats.map(c=>`<button class="chat-item ${state.chat?._id===c._id?'active':''}" data-chat="${c._id}">${icon('chat')} ${escapeHTML(c.title)}</button>`).join('')}</aside><section class="card chat-main"><div class="chat-title row between"><div class="row">${icon('spark')}<strong>AI ustoz</strong><span class="pill neutral">${state.info.aiConfigured?'AI ULANGAN':'SOZLASH KERAK'}</span></div>${state.chat?'<button class="iconbtn" id="delete-chat" aria-label="Suhbatni o‘chirish">'+icon('trash')+'</button>':''}</div><div class="messages" id="messages">${state.chat?.messages.length?state.chat.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><div class="message-label">${m.role==='user'?'SIZ':'AI USTOZ'}</div>${escapeHTML(m.content)}</div>`).join(''):`<div class="empty">${icon('spark')}<h3>Qaysi savoldan boshlaymiz?</h3><p>Shoshilmaymiz. Birgalikda tushunib olamiz.</p></div><div class="chat-suggestions"><button data-prompt="Kasrlarni qo‘shishni sodda misol bilan tushuntir.">½ Kasrlarni sodda qilib tushuntir</button><button data-prompt="Foizlar bo‘yicha savol-javob o‘ynaymiz. Birinchi savolni ber, javobimni kut.">% Men bilan savol-javob o‘yna</button><button data-prompt="3x + 6 = 21 tenglamasini yechishga ishora ber, javobni darrov aytma.">x Tenglamada yordam kerak</button></div>`}</div><form class="composer" id="chat-form"><label class="grow"><span class="sr-only" hidden>Savolingiz</span><input name="message" aria-label="AI ustozga savol" required maxlength="1800" placeholder="Savolingizni yozing…" autocomplete="off"></label><button class="btn" type="submit" aria-label="Yuborish">${icon('send')}</button></form></section></div>`;}
function bindAI(){if($('#new-chat'))$('#new-chat').onclick=e=>action(e.currentTarget,async()=>{state.chat=await api('/chats','POST',{title:'Yangi suhbat'});await route();});$$('[data-chat]').forEach(b=>b.onclick=e=>action(e.currentTarget,async()=>{state.chat=await api('/chats/'+b.dataset.chat);await route();}));formBind('#chat-form',async d=>{if(!state.chat)state.chat=await api('/chats','POST',{title:'Yangi suhbat'});const input=$('#chat-form input');input.disabled=true;const waiting=document.createElement('p');waiting.textContent='AI ustoz o‘ylayapti…';waiting.className='muted';$('#messages').append(waiting);try{state.chat=await api('/chats/'+state.chat._id+'/messages','POST',d);await route();}finally{input.disabled=false;waiting.remove();}});$$('[data-prompt]').forEach(b=>b.onclick=()=>{$('#chat-form input').value=b.dataset.prompt;$('#chat-form input').focus();});if($('#delete-chat'))$('#delete-chat').onclick=()=>{modal('<h2>Suhbat o‘chirilsinmi?</h2><p>Bu suhbat matnini qayta tiklab bo‘lmaydi.</p><button class="btn danger" id="confirm-delete-chat">Suhbatni o‘chirish</button>');$('#confirm-delete-chat').onclick=e=>action(e.currentTarget,async()=>{await api('/chats/'+state.chat._id,'DELETE');state.chat=null;closeModal();await route();});};if($('#messages'))$('#messages').scrollTop=$('#messages').scrollHeight;}
async function plansPage(){const orders=await api('/orders');return `${head('O‘sish uchun o‘z paketingizni tanlang.','Bitta obuna — aniq imkoniyatlar. Avtomatik yechib olish yo‘q.',`<span class="pill">Joriy: ${state.info.plans[state.me.effectivePlan].name}</span>`)}<div class="notice"><strong>To‘lov tartibi:</strong> buyurtma qoldiring, haqiqiy to‘lovni rekvizitlar orqali amalga oshiring. Administrator tushumni tekshirib tasdiqlagandan keyin paket 30 kunga yoqiladi. Bu sahifa kartadan pul yechmaydi.</div>${priceCards(true)}<section class="card space"><h2>To‘lov ma’lumotlari</h2><p class="space">${escapeHTML(state.info.paymentInfo)}</p></section><section class="card space"><h2>Buyurtmalarim</h2>${orders.length?`<div class="table-wrap space"><table><thead><tr><th>Paket</th><th>Summa</th><th>Holat</th><th>Sana</th><th></th></tr></thead><tbody>${orders.map(o=>`<tr><td>${state.info.plans[o.plan].name}</td><td>${money(o.amount)} so‘m</td><td>${orderStatus(o.status)}</td><td>${date(o.createdAt)}</td><td>${o.status==='pending'?`<button class="btn small ghost" data-cancel-order="${o._id}">Bekor qilish</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Buyurtmalar yo‘q','Paket tanlaganingizda buyurtmangiz shu yerda ko‘rinadi.')}</section>`;}
const orderStatus=s=>({pending:'Kutilmoqda',processing:'Tekshirilmoqda',approved:'Tasdiqlangan',rejected:'Rad etilgan',cancelled:'Bekor qilingan'})[s]||s;
function bindPlans(){ $$('[data-buy]').forEach(b=>b.onclick=()=>{const p=state.info.plans[b.dataset.buy];modal(`<h2>${p.name} paketi</h2><p>${money(p.price)} so‘m / 30 kun. Buyurtma tasdiqlanmaguncha pullik imkoniyatlar yoqilmaydi.</p><p>${escapeHTML(state.info.paymentInfo)}</p><form id="buy-form"><label class="field"><span>To‘lov identifikatori yoki izoh (ixtiyoriy)</span><input name="reference" maxlength="150" placeholder="Tranzaksiya raqami; karta raqami emas"></label><button type="submit" class="btn full">Buyurtma yaratish</button></form>`);formBind('#buy-form',async d=>{await api('/orders','POST',{plan:b.dataset.buy,...d});closeModal();toast('Buyurtma yaratildi. Tasdiqni kuting.');await route();});});$$('[data-cancel-order]').forEach(b=>b.onclick=e=>action(e.currentTarget,async()=>{await api('/orders/'+b.dataset.cancelOrder,'DELETE');await route();toast('Buyurtma bekor qilindi.');}));}
function settingsPage(){const u=state.user;return `${head('Sizga mos sozlamalar.','Profil, mavzu va hisob xavfsizligi.')}<div class="grid2"><form id="profile-form" class="card"><h2>Profil ma’lumotlari</h2><label class="field space"><span>Ism</span><input name="name" value="${escapeHTML(u.name)}" minlength="2" maxlength="60" required></label><label class="field"><span>Email · o‘zgartirilmaydi</span><input value="${escapeHTML(u.email)}" disabled></label><label class="field"><span>Sinf</span><select name="grade">${Array.from({length:9},(_,i)=>`<option value="${i+3}" ${i+3===u.grade?'selected':''}>${i+3}-sinf</option>`).join('')}</select></label><label class="field"><span>Sevimli matematika yo‘nalishi</span><select name="topic">${Object.entries(topicNames).map(([k,v])=>`<option value="${k}" ${k===u.topic?'selected':''}>${v}</option>`).join('')}</select></label><button class="btn" type="submit">O‘zgarishlarni saqlash ${icon('check')}</button></form><div class="stack"><form class="card" id="password-form"><h2>Parolni yangilash</h2><label class="field space"><span>Joriy parol</span><input type="password" name="current" required autocomplete="current-password" maxlength="72"></label><label class="field"><span>Yangi parol · kamida 10 belgi</span><input type="password" name="password" minlength="10" maxlength="72" required autocomplete="new-password"></label><button class="btn secondary" type="submit">Parolni yangilash</button><p class="form-note">Boshqa qurilmalardagi sessiyalar tugatiladi.</p></form><section class="card"><h2>Ko‘rinish</h2><div class="row between space"><p>Yorug‘ yoki qorong‘i rejim</p>${themeButton()}</div><a href="#/privacy" class="btn ghost small space">Maxfiylik qoidalari</a></section></div></div>`;}
function bindSettings(){formBind('#profile-form',async d=>{const r=await api('/me','PATCH',{...d,grade:Number(d.grade)});state.user=r.user;toast('Profil saqlandi.');await route();});formBind('#password-form',async(d,f)=>{await api('/me/password','POST',d);f.reset();toast('Parol yangilandi. Boshqa sessiyalar tugatildi.');});}
async function adminHome(){const s=await api('/admin/stats');return `${head('Platforma bir qarashda.','Ko‘rsatkichlar MongoDB dagi haqiqiy yozuvlardan hisoblanadi.',`<button class="btn secondary" id="refresh-admin">${icon('chart')} Yangilash</button>`)}<div class="grid4">${stat('Foydalanuvchilar',s.users,`${s.students} o‘quvchi · ${s.parents} ota-ona`,'users')}${stat('Yakunlangan testlar',s.tests,`${s.average}% o‘rtacha natija`,'test')}${stat('Tasdiqlangan tushum',money(s.revenue),`So‘m · admin tasdiqlagan buyurtmalar`,'wallet')}${stat('Kutilayotgan to‘lovlar',s.pending,'Qo‘lda tekshirish talab etiladi','clock')}</div><div class="dashboard-columns"><section class="card"><div class="section-head"><h2>So‘nggi 7 kun · testlar</h2><span class="pill neutral">TOSHKENT VAQTI</span></div><div class="chart">${s.chart.map(x=>`<div class="barcol"><strong>${x.count}</strong><meter min="0" max="${Math.max(1,...s.chart.map(x=>x.count))}" value="${x.count}" aria-label="${x.day}: ${x.count} ta test"></meter><small>${x.day.slice(5)}</small></div>`).join('')}</div>${!s.tests?'<p class="form-note">Hali test yo‘q. Birinchi natijadan keyin grafik to‘ladi.</p>':''}</section><section class="card"><h2>Ulanishlar</h2>${Object.entries({mongo:'MongoDB',ai:'AI ustoz',telegram:'Telegram bot'}).map(([k,v])=>`<div class="connection"><span>${v}</span><span><i class="status-dot ${s.integrations[k]?'':'off'}"></i>${s.integrations[k]?'Sozlangan':'Sozlanmagan'}</span></div>`).join('')}<div class="connection"><span>To‘lov</span><span>Qo‘lda tasdiqlash</span></div><p class="form-note">«Sozlangan» — kalit mavjudligi. Jonli xizmatning javob berishi alohida tekshiriladi.</p><a class="btn ghost small full space" href="#/app/system">Tizim tafsilotlari →</a></section></div><section class="card space"><h2>Platformadagi oxirgi faoliyat</h2>${activities(s.activity.slice(0,10))}</section>`;}
async function usersPage(){const params=new URLSearchParams(location.hash.split('?')[1]||'');const search=params.get('search')||'',page=params.get('page')||'1';const d=await api(`/admin/users?search=${encodeURIComponent(search)}&page=${page}`);return `${head('Foydalanuvchilar.','Hisoblarni qidiring va zarur bo‘lsa kirishni cheklang.')}<section class="card"><form class="search-form" id="user-search"><input name="search" aria-label="Ism yoki email" value="${escapeHTML(search)}" placeholder="Ism yoki email bo‘yicha qidirish"><button class="btn secondary" type="submit">Qidirish</button></form><small>Jami ${d.count} ta hisob</small><div class="table-wrap"><table><thead><tr><th>Ism / email</th><th>Rol</th><th>Paket</th><th>Holat</th><th>Amal</th></tr></thead><tbody>${d.rows.map(u=>`<tr><td><strong>${escapeHTML(u.name)}</strong><br><small>${escapeHTML(u.email)}</small></td><td>${({student:'O‘quvchi',parent:'Ota-ona',admin:'Admin'})[u.role]}</td><td>${state.info.plans[u.plan].name}${u.planUntil?'<br><small>'+date(u.planUntil)+'</small>':''}</td><td><span class="pill neutral">${u.blocked?'Bloklangan':'Faol'}</span></td><td>${u.role!=='admin'?`<button class="btn small ${u.blocked?'secondary':'danger'}" data-block="${u._id}" data-blocked="${u.blocked}">${u.blocked?'Ochish':'Bloklash'}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><div class="row between space"><span>${d.page}-sahifa</span><div class="row">${d.page>1?`<a class="btn small ghost" href="#/app/users?page=${d.page-1}&search=${encodeURIComponent(search)}">← Oldingi</a>`:''}${d.page*20<d.count?`<a class="btn small ghost" href="#/app/users?page=${d.page+1}&search=${encodeURIComponent(search)}">Keyingi →</a>`:''}</div></div></section>`;}
async function ordersPage(){const orders=await api('/admin/orders');return `${head('To‘lov buyurtmalari.','Tasdiqlashdan oldin haqiqiy tushumni bank yoki to‘lov hisobingizdan tekshiring.')}<div class="notice"><strong>Tasdiqlash</strong> paketni shu kundan 30 kunga faollashtiradi. Kiritilgan izohning o‘zi to‘lov isboti emas. Bu tizim avtomatik to‘lov provayderiga ulanmagan.</div><section class="card">${orders.length?`<div class="table-wrap"><table><thead><tr><th>Mijoz</th><th>Paket / summa</th><th>Izoh</th><th>Holat</th><th>Amal</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${escapeHTML(o.userId?.name||'O‘chirilgan')}<br><small>${escapeHTML(o.userId?.email)}</small></td><td>${state.info.plans[o.plan].name}<br>${money(o.amount)} so‘m</td><td>${escapeHTML(o.reference||'—')}</td><td>${orderStatus(o.status)}</td><td>${o.status==='pending'?`<div class="row"><button class="btn small" data-review="${o._id}" data-action="approve">Tasdiqlash</button><button class="btn small danger" data-review="${o._id}" data-action="reject">Rad etish</button></div>`:date(o.reviewedAt)}</td></tr>`).join('')}</tbody></table></div>`:empty('Buyurtmalar hali yo‘q','Mijozlar paket tanlaganda buyurtmalar shu yerga keladi.')}</section>`;}
async function systemPage(){const [s,a]=await Promise.all([api('/admin/stats'),api('/admin/audit')]);return `${head('Tizim va nazorat.','Integratsiyalar, Telegram navbati va admin amallari jurnali.')}<div class="grid2"><section class="card"><h2>Telegram xabarlari</h2>${s.queue.length?s.queue.map(x=>`<div class="connection"><span>${escapeHTML(x._id)}</span><strong>${x.count}</strong></div>`).join(''):'<p class="space">Xabarlar navbati bo‘sh.</p>'}<button class="btn secondary space" id="retry-telegram">Yuborilmagan xabarlarni qayta navbatga olish</button><p class="form-note">Bot kaliti, internet ulanishi va ota-onaning botni bloklamaganini tekshiring.</p></section><section class="card"><h2>Xavfsizlik asoslari</h2><div class="connection">Serverda rol va oila ruxsatlari tekshiriladi ${icon('shield')}</div><div class="connection">Parollar bcrypt bilan xeshlanadi ${icon('check')}</div><div class="connection">Sessiya HttpOnly cookie orqali ${icon('check')}</div><div class="connection">API kalitlari faqat serverda ${icon('check')}</div><p class="form-note">Ishlab chiqarishda HTTPS, DB autentifikatsiyasi, zaxira nusxa va mustaqil xavfsizlik tekshiruvi kerak.</p></section></div><section class="card space"><h2>Admin amallari jurnali</h2>${a.length?`<div class="table-wrap"><table><thead><tr><th>Amal</th><th>Obyekt</th><th>Vaqt</th></tr></thead><tbody>${a.map(x=>`<tr><td>${escapeHTML(x.action)}</td><td>${escapeHTML(x.target)}</td><td>${date(x.createdAt)}</td></tr>`).join('')}</tbody></table></div>`:empty('Jurnal hali bo‘sh','Bloklash va to‘lov tasdiqlash amallari yozib boriladi.')}</section>`;}
function bindAdmin(){if($('#refresh-admin'))$('#refresh-admin').onclick=()=>route();formBind('#user-search',async d=>go('/app/users?search='+encodeURIComponent(d.search)));$$('[data-block]').forEach(b=>b.onclick=()=>{const blocked=b.dataset.blocked==='false';modal(`<h2>Hisob ${blocked?'bloklansinmi':'qayta ochilsinmi'}?</h2><p>${blocked?'Barcha faol sessiyalar tugatiladi va hisobga kirish cheklanadi.':'Foydalanuvchi qayta hisobga kira oladi.'}</p><button class="btn" id="confirm-block">Tasdiqlash</button>`);$('#confirm-block').onclick=e=>action(e.currentTarget,async()=>{await api('/admin/users/'+b.dataset.block,'PATCH',{blocked});closeModal();await route();toast('Holat yangilandi.');});});$$('[data-review]').forEach(b=>b.onclick=()=>{const approve=b.dataset.action==='approve';modal(`<h2>${approve?'To‘lov tasdiqlansinmi?':'Buyurtma rad etilsinmi?'}</h2><p>${approve?'Haqiqiy pul tushganini tekshirgan bo‘lsangiz tasdiqlang. Paket 30 kunga faollashadi.':'Pullik paket faollashmaydi. Foydalanuvchi yangi buyurtma bera oladi.'}</p><button class="btn" id="confirm-review">${approve?'Tushum tekshirildi, tasdiqlash':'Rad etish'}</button>`);$('#confirm-review').onclick=e=>action(e.currentTarget,async()=>{await api('/admin/orders/'+b.dataset.review+'/review','POST',{action:b.dataset.action});closeModal();await route();toast('Buyurtma yangilandi.');});});if($('#retry-telegram'))$('#retry-telegram').onclick=e=>action(e.currentTarget,async()=>{await api('/admin/telegram/retry','POST');await route();toast('Xabarlar qayta navbatga olindi.');});}
function privacy(){ $('#app').innerHTML=`<div class="public"><nav class="nav-public">${brand()}${themeButton()}</nav><section class="public-section"><div class="lesson-view"><h1>Maxfiylik va foydalanish</h1><section class="card space"><h2>Nimalar saqlanadi?</h2><p class="space">Ism, email, xeshlangan parol, sinf, test javoblari va natijalari, o‘quv faoliyati, AI suhbatlari va paket buyurtmalari MongoDB da saqlanadi.</p><h2 class="space">Ota-ona nimani ko‘radi?</h2><p class="space">Faqat kod orqali bog‘langan farzandning test natijalari va sayt ichidagi o‘quv harakatlarini. AI suhbatining to‘liq matni ko‘rsatilmaydi. Sayt boshqa ilova yoki qurilmangizdagi harakatlarni kuzatmaydi.</p><h2 class="space">Tashqi xizmatlar</h2><p class="space">AI ishlatilganda suhbatning so‘nggi xabarlari AI provayderiga yuboriladi. Telegram yoqilganda farzand ismi va o‘quv faoliyatining qisqa xulosasi Telegramga yuboriladi. Shaxsiy, tibbiy yoki to‘lov karta ma’lumotlarini AI chatiga yozmang.</p><h2 class="space">Hisob va to‘lovlar</h2><p class="space">Bolalar ota-onasi yordamida hisob ochsin. Paket narxlari boshlang‘ich taklif hisoblanadi. To‘lov qo‘lda tekshiriladi; sayt karta ma’lumotlarini qabul qilmaydi va avtomatik pul yechmaydi. AI javoblari doim ham to‘g‘ri bo‘lmasligi mumkin.</p><h2 class="space">Boshqarish</h2><p class="space">AI suhbatini o‘zingiz o‘chirishingiz, Telegramni uzishingiz, ota-ona esa farzandni oiladan ajratishi mumkin. Barcha hisob ma’lumotlarini o‘chirish uchun platforma egasiga murojaat qiling. Ommaviy ishga tushirishdan oldin egasi o‘z aloqa manzili, saqlash muddati va amaldagi huquqiy shartlarini qo‘shishi kerak.</p><a class="btn space" href="${state.user?'#/app':'#/'}">${icon('back')} Qaytish</a></section></div></section></div>`;bindTheme();}
async function route(){const version=++state.routeVersion;const path=(location.hash.slice(1)||'/').split('?')[0];closeModal();if(path==='/privacy'){privacy();return;}if(['/','/how','/pricing'].includes(path)){landing();return;}if(path==='/login'||path==='/register'){if(state.user){go('/app');return;}authPage(path==='/register');return;}if(!path.startsWith('/app')){go('/');return;}if(!state.user){go('/login');return;}shell(path);try{state.me=await api('/me');state.user=state.me.user;let html;const role=state.user.role;
 if(path==='/app')html=role==='student'?await studentHome():role==='parent'?await familyPage(true):await adminHome();
 else if(path==='/app/settings')html=settingsPage();
 else if(path==='/app/plans'&&role!=='admin')html=await plansPage();
 else if(path==='/app/family'&&role!=='admin')html=await familyPage();
 else if(role==='student'){
  if(path==='/app/learn'||path.startsWith('/app/learn/'))html=await learnPage(path.split('/')[3]);
  else if(path==='/app/test')html=await testPage();else if(path==='/app/map')html=await mapPage();else if(path==='/app/history')html=await historyPage();else if(path==='/app/ai')html=await aiPage();else if(path.startsWith('/app/result/'))html=resultHTML(await api('/tests/'+path.split('/')[3]));
 }else if(role==='parent'){
  if(path==='/app/telegram')html=await telegramPage();else if(path==='/app/activity')html=head('O‘quv faoliyati tarixi.','Bog‘langan farzandlaringizning oxirgi 60 ta harakati.')+'<section class="card">'+activities(await api('/activities'))+'</section>';
 }else if(role==='admin'){
  if(path==='/app/users')html=await usersPage();else if(path==='/app/orders')html=await ordersPage();else if(path==='/app/system')html=await systemPage();
 }
 if(version!==state.routeVersion)return;if(!html)html=empty('Bu sahifa sizning rolingiz uchun emas','Bosh sahifadan davom eting.','<a class="btn" href="#/app">Bosh sahifa</a>');$('#view').innerHTML=html;bindTheme();bindLesson();bindTests();bindFamily();bindTelegram();bindAI();bindPlans();bindSettings();bindAdmin();window.scrollTo(0,0);
 }catch(e){if(version===state.routeVersion&&$('#view'))$('#view').innerHTML=empty('Ma’lumotni yuklab bo‘lmadi',escapeHTML(e.message),'<button class="btn" id="retry-page">Qayta urinish</button>');if($('#retry-page'))$('#retry-page').onclick=()=>route();}}
window.addEventListener('hashchange',route);
async function init(){try{state.info=await api('/public');try{state.me=await api('/me');state.user=state.me.user;}catch{}await route();}catch(e){$('#app').innerHTML=`<div class="loading"><h2>Serverga ulanib bo‘lmadi</h2><p class="space">${escapeHTML(e.message)}</p><p class="space">Loyiha papkasida npm start buyrug‘ini bajaring va http://localhost:3000 ni oching.</p><button class="btn space" id="reload">Qayta urinish</button></div>`;$('#reload').onclick=()=>location.reload();}}
init();
